onClick:
{{
  (() => {
    const correo = (inpAdminInvitarCorreo.text || "").trim();
    const nombre = (inpAdminInvitarNombre.text || "").trim();
    const apellido = (inpAdminInvitarApellido.text || "").trim();
    const empresa = selAdminInvitarEmpresa.selectedOptionValue;
    const rol = selAdminInvitarRol.selectedOptionValue;

    if (!correo) {
      showAlert("Ingresa el correo electrónico.", "warning");
      return;
    }

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(correo)) {
      showAlert("Ingresa un correo electrónico válido.", "warning");
      return;
    }

    if (!nombre || !apellido) {
      showAlert("Ingresa el nombre y apellido del usuario.", "warning");
      return;
    }

    if (!empresa) {
      showAlert("Selecciona la empresa.", "warning");
      return;
    }

    if (!rol) {
      showAlert("Selecciona el rol del usuario.", "warning");
      return;
    }

    showAlert(
      "Formulario válido. La invitación aún no ha sido enviada.",
      "success"
    );
  })()
}}
